"""Browser-local JRDB provisional-mail import (code only, no licensed data)."""
HTML = "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>競馬ナイン｜JRDBメール取り込み（本人用）</title><link rel=\"stylesheet\" href=\"/jrdb-mail-local.css\"></head><body><main>\n<a href=\"/\">← 本人用ホーム</a>\n<h1>🏇 JRDBメールを取り込む（追加・更新）</h1>\n<p class=\"notice\"><strong>本人用・端末内のみ</strong>。JRDBから届いた「【想確】」メールの本文を貼り付けると、開催日・競馬場・レース別に整理して、この端末内に保存するで。サーバーへのアップロードやGmailへの自動接続はしません。</p>\n<p class=\"warning\">これは<strong>想定確定</strong>で、JRAの最終出馬表・馬番・枠順・取消・当日馬場ではありません。3連単やS/A/B/Cを実戦予想として自動生成しません。転載・一般公開・他人への共有は禁止。</p>\n<section><h2>1. メール本文を貼り付け</h2>\n<label for=\"mailText\">JRDBから届いたメール本文（東京・京都・福島など、1通ずつ、または複数通まとめて）</label>\n<textarea id=\"mailText\" rows=\"8\" maxlength=\"192000\" placeholder=\"■想定確定&#10;&#10;2026年11月7日（土） 5回東京1日目 09:55発走&#10;1Ｒ&#10;...\"></textarea>\n<button id=\"importMail\" type=\"button\">この端末に追加・更新する</button>\n<p id=\"message\" role=\"status\" class=\"hint\">今日・明日に届く同じ種類のメールは複数通まとめて貼ってOK。更新がある開催は、確認してから入れ替えるで。原文は保存しません。</p></section>\n<section><h2>2. 取り込んだ開催を選択</h2><p class=\"hint\">同じ日付・競馬場なら更新を比較。別の日付や競馬場はそのまま残すで。枠順が付いた確定出馬表は別形式やから、想定メールとして誤って読み込まへん。</p>\n<label for=\"chooseMeeting\">日付・競馬場</label><select id=\"chooseMeeting\"><option value=\"\">取り込んだ開催はまだありません</option></select>\n<p id=\"meetingInfo\" class=\"hint\"></p><div id=\"raceList\"></div><button id=\"deleteMeeting\" type=\"button\" class=\"secondary\">選択した開催だけ削除</button></section>\n<section><button id=\"clearAll\" type=\"button\" class=\"secondary\">この端末の取り込みデータをすべて消す</button>\n<p class=\"hint\">保存先は、このブラウザーの保存領域だけ。Safariと別ブラウザーでは共有されへん。閲覧データを消すと、この予定も消えるで。</p><a href=\"/my-tickets\">3連単の下書きを開く（馬番確定後・手動）</a></section>\n</main><script src=\"/jrdb-mail-local.js\" defer></script></body></html>"
CSS = "*{box-sizing:border-box}html{color-scheme:dark}body{background:#0a172a;color:#f2f6ff;margin:0;font:15px/1.6 system-ui,sans-serif}main{max-width:780px;margin:auto;padding:18px 14px 50px}h1{font-size:23px;line-height:1.4}h2{font-size:19px;margin-top:0}a{color:#edce82}section{background:#162d49;border:1px solid #42607e;border-radius:15px;padding:15px;margin:16px 0}.notice,.warning{border-radius:11px;padding:12px;background:#243648}.warning{background:#42321e;color:#ffe0aa}label{display:block;font-weight:700;margin:10px 0 7px}textarea,select{display:block;width:100%;font:inherit;padding:12px;background:#0a2036;color:#fff;border:1px solid #7893ad;border-radius:10px}textarea{min-height:160px;resize:vertical}button{width:100%;min-height:48px;margin:10px 0;border:0;border-radius:10px;background:#f1d07b;color:#172b3d;font:inherit;font-weight:800}button.secondary{background:#344b62;color:#e2eaf4}.hint{color:#bcd0e4;font-size:13px}details{background:#0e2137;border:1px solid #425b76;border-radius:10px;margin:9px 0;padding:10px 12px}summary{font-weight:750;cursor:pointer}ul{margin:8px 0 4px;padding-left:23px}li{padding:2px 0}small{display:block;color:#d7bfd2;font-size:12px;margin-top:6px}strong{color:#f0d18e}.warning{border-left:3px solid #e9b968}textarea:focus-visible,select:focus-visible,button:focus-visible{outline:3px solid #f1d07b;outline-offset:2px}"
JS = "'use strict';\n// Client-only, single-person email conversion. No fetch/XHR/analytics,\n// no raw mailbox text persistence and no provider rights transfer.\n(function(){\nconst KEY='keiba-nine-jrdb-personal-mail-v1', MAX_MAIL=64000, MAX_BATCH=12, MAX_TOTAL=192000, MAX_SAVED=48;\nconst TRACKS=['札幌','函館','福島','新潟','東京','中山','中京','京都','阪神','小倉'];\nconst $=id=>document.getElementById(id);\nconst make=(tag,text)=>{const node=document.createElement(tag);node.textContent=String(text);return node;};\nfunction validDate(year,month,day){\n const d=new Date(Date.UTC(Number(year),Number(month)-1,Number(day)));\n return d.toISOString().slice(0,10)===year+'-'+month.padStart(2,'0')+'-'+day.padStart(2,'0');\n}\nfunction parseJRDBMail(raw){\n if(typeof raw!=='string'||raw.length<100||raw.length>MAX_MAIL||!raw.includes('■想定確定'))\n  throw Error('JRDBの「■想定確定」メール本文を1通ずつ貼ってな。');\n const lines=raw.normalize('NFKC').split(/\\r?\\n/);\n const headers=/^(20\\d{2})年\\s*(\\d{1,2})月\\s*(\\d{1,2})日.*?(札幌|函館|福島|新潟|東京|中山|中京|京都|阪神|小倉)(\\d+)日目\\s+(\\d{1,2}):(\\d{2})発走/;\n let date=null,track=null,previous=null,current=null,inEntries=false;\n const races=[],seen=new Set();\n for(const original of lines){\n  const line=original.trim();\n  if(/^All Rights Reserved|^配\\s*信\\s*:|^このメールに掲載/.test(line))break;\n  const h=headers.exec(line);\n  if(h){\n   const [unused,y,m,d,t,dayNumber,hh,mm]=h;\n   if(!validDate(y,m,d)||Number(hh)>23||Number(mm)>59)\n    throw Error('開催日時が不正です。');\n   const nextDate=y+'-'+m.padStart(2,'0')+'-'+d.padStart(2,'0');\n   if(date!==null&&(date!==nextDate||track!==t))\n    throw Error('1通の中に異なる日付・競馬場が混じっています。');\n   date=nextDate;track=t;previous={time:hh.padStart(2,'0')+':'+mm, day:dayNumber};\n   current=null;inEntries=false;continue;\n  }\n  const race=/^(\\d{1,2})R$/.exec(line);\n  if(race&&previous){\n   const number=Number(race[1]);\n   if(number<1||number>12||seen.has(number)||races.length>=12)\n    throw Error('レース番号の重複、または対象外のRを検出しました。');\n   seen.add(number);\n   current={race:number,postTime:previous.time,expected:null,horses:[]};\n   races.push(current);\n   inEntries=false;previous=null;continue;\n  }\n  if(!current)continue;\n  if(current.expected===null){\n   const x=/(\\d{1,2})頭/.exec(line);\n   if(x){current.expected=Number(x[1]);if(current.expected<1||current.expected>18)\n     throw Error('出走予定頭数が不正です。');}\n  }\n  if(/前評\\s+.*馬名/.test(line)){inEntries=true;continue;}\n  if(!inEntries)continue;\n  const entrant=/^(?:B\\s+)?([^\\s]+)\\s+(牡|牝|セ)\\s+(\\d{1,2})\\s+/.exec(line);\n  if(entrant){\n   const name=entrant[1];\n   if(name.length>35||current.horses.includes(name))\n    throw Error('馬名が重複または長すぎます。');\n   if(current.horses.length>=18)throw Error('登録頭数の上限を超えています。');\n   current.horses.push(name);\n  }\n }\n if(!date||!track||!races.length)throw Error('開催日・競馬場・レースを読み取れませんでした。');\n for(const race of races){\n  if(race.expected===null||race.horses.length!==race.expected)\n   throw Error(race.race+'Rの頭数が一致しません。メール本文が途中で切れていないか確認してな。');\n }\n races.sort((a,b)=>a.race-b.race);\n return {date,track,kind:'jrdb-provisional',races};\n}\n\nfunction parseMailBatch(raw){\n if(typeof raw!=='string'||raw.length<100||raw.length>MAX_TOTAL)\n  throw Error('メール本文を貼ってください。まとめて貼れる量は19万文字までです。');\n const normal=raw.replace(/\\r\\n/g,'\\n');\n const starts=[...normal.matchAll(/^■想定確定[ \\t]*$/gm)].map(x=>x.index);\n if(!starts.length||starts.length>MAX_BATCH)\n  throw Error('「■想定確定」メールの本文を1〜12通貼ってください。');\n const meetings=[],keys=new Set();\n for(let i=0;i<starts.length;i++){\n  const item=normal.slice(starts[i],i+1<starts.length?starts[i+1]:normal.length);\n  if(item.length>MAX_MAIL)throw Error((i+1)+'通目が長すぎます。1通64,000文字以内にしてください。');\n  const parsed=parseJRDBMail(item);\n  const key=parsed.date+'|'+parsed.track;\n  if(keys.has(key))throw Error('同じ日付・競馬場のメールが重複しています。1通ずつ確認してな。');\n  keys.add(key);meetings.push(parsed);\n }\n return meetings;\n}\nfunction compareChanges(oldValue,newValue){\n if(!oldValue)return {changed:true,added:newValue.races.length,modified:0};\n const oldRaces=new Map(oldValue.races.map(r=>[r.race,r]));\n if(oldValue.races.some(r=>!newValue.races.some(n=>n.race===r.race)))\n  throw Error(newValue.date+' '+newValue.track+'の新しいメールは以前のレースが欠けています。古い予定は保護したで。');\n let added=0,modified=0;\n for(const race of newValue.races){\n  const old=oldRaces.get(race.race);\n  if(!old){added+=1;continue;}\n  if(old.postTime!==race.postTime||old.expected!==race.expected||\n     JSON.stringify(old.horses)!==JSON.stringify(race.horses))modified+=1;\n }\n return {changed:added+modified>0,added,modified};\n}\nfunction validSaved(x){\n return x&&x.kind==='jrdb-provisional'&&typeof x.date==='string'&&\n /^\\d{4}-\\d{2}-\\d{2}$/.test(x.date)&&TRACKS.includes(x.track)&&\n Array.isArray(x.races)&&x.races.length>=1&&x.races.length<=12&&\n x.races.every(r=>r&&Number.isInteger(r.race)&&r.race>=1&&r.race<=12&&\n /^\\d{2}:\\d{2}$/.test(r.postTime)&&Number.isInteger(r.expected)&&\n r.expected>=1&&r.expected<=18&&Array.isArray(r.horses)&&\n r.horses.length===r.expected&&r.horses.every(n=>typeof n==='string'&&n.length>=1&&n.length<=35))&&\n new Set(x.races.map(r=>r.race)).size===x.races.length;\n}\nlet meetings=[];\ntry{\n const data=JSON.parse(localStorage.getItem(KEY)||'[]');\n if(Array.isArray(data))meetings=data.slice(-MAX_SAVED).filter(validSaved);\n}catch(_){meetings=[];}\nfunction show(){\n const chosen=$('chooseMeeting').value;\n const select=$('chooseMeeting');select.replaceChildren();\n select.append(make('option',meetings.length?'開催を選択':'取り込み済みの開催はありません'));\n select.children[0].value='';\n const sorted=meetings.slice().sort((a,b)=>b.date.localeCompare(a.date)||TRACKS.indexOf(a.track)-TRACKS.indexOf(b.track));\n for(const item of sorted){\n  const opt=make('option',item.date+' '+item.track+'｜'+item.races.length+'R');\n  opt.value=item.date+'|'+item.track;select.append(opt);\n }\n const key=sorted.some(m=>m.date+'|'+m.track===chosen)?chosen:\n  (sorted[0]?sorted[0].date+'|'+sorted[0].track:'');\n select.value=key;\n const chosenMeeting=sorted.find(m=>m.date+'|'+m.track===key);\n const list=$('raceList');list.replaceChildren();\n if(!chosenMeeting){$('meetingInfo').textContent='まだ開催データがありません。';return;}\n const sum=chosenMeeting.races.reduce((n,r)=>n+r.expected,0);\n $('meetingInfo').textContent=chosenMeeting.date+'・'+chosenMeeting.track+\n  '／'+chosenMeeting.races.length+'レース・想定登録'+sum+'頭。馬番・枠・取消は未確定。';\n for(const race of chosenMeeting.races){\n  const details=document.createElement('details');\n  details.append(make('summary',race.race+'R｜'+race.postTime+'（想定）｜'+race.expected+'頭'));\n  const small=make('small','※想定資料。馬番・枠順はありません。JRA出馬表で最終確認が必要。');\n  details.append(small);\n  const names=document.createElement('ul');\n  for(const name of race.horses)names.append(make('li',name));\n  details.append(names);list.append(details);\n }\n}\n$('importMail').onclick=()=>{\n try{\n  // Validate the entire pasted batch BEFORE changing any saved meeting.\n  const incoming=parseMailBatch($('mailText').value);\n  const updates=[],replacement=meetings.slice();\n  let added=0,modified=0,changedExisting=false;\n  for(const item of incoming){\n   const index=replacement.findIndex(m=>m.date===item.date&&m.track===item.track);\n   const before=index<0?null:replacement[index];\n   const change=compareChanges(before,item);\n   if(!change.changed)continue;\n   if(index>=0)changedExisting=true;\n   if(index<0)replacement.push(item);\n   else replacement[index]=item;\n   added+=change.added;modified+=change.modified;\n   updates.push(item.date+' '+item.track+'（新規'+change.added+'R・変更'+change.modified+'R）');\n  }\n  if(replacement.length>MAX_SAVED)\n   throw Error('最大48開催まで保存できます。不要な開催を削除してから再試行してな。');\n  if(changedExisting&&\n     !confirm('取り込み予定 '+incoming.length+'通\\n'+updates.join('\\n')+\n      '\\nほかの日付・競馬場、買い目・購入記録は変更しません。更新しますか？'))\n   return;\n  if(updates.length){\n   // One transaction: on quota failure, leave the previous localStorage intact.\n   localStorage.setItem(KEY,JSON.stringify(replacement));\n   meetings=replacement;\n  }\n  $('mailText').value='';\n  show();\n  const last=incoming[incoming.length-1];\n  $('chooseMeeting').value=last.date+'|'+last.track;\n  $('chooseMeeting').onchange();\n  $('message').textContent=incoming.length+'通を確認。'+updates.length+'開催を追加・更新、'+\n   (incoming.length-updates.length)+'開催は変更なし。新規'+added+'R、変更'+modified+\n   'R。原文は保存せず、馬番・枠順は未確定のままやで。';\n }catch(e){$('message').textContent='取り込めません：'+(e&&e.message||'メール形式を確認してな。');}\n};\n$('chooseMeeting').onchange=()=>{\n const key=$('chooseMeeting').value;\n const selected=meetings.find(m=>m.date+'|'+m.track===key);\n const list=$('raceList');list.replaceChildren();\n if(!selected){$('meetingInfo').textContent='開催を選んでな。';return;}\n $('meetingInfo').textContent=selected.date+' '+selected.track+'｜'+selected.races.length+'R（想定・馬番未確定）';\n for(const race of selected.races){\n  const details=document.createElement('details');\n  details.append(make('summary',race.race+'R｜'+race.postTime+'（想定）｜'+race.expected+'頭'));\n  details.append(make('small','馬番・枠順・取消・当日馬場は未確定。JRA公式で照合してな。'));\n  const names=document.createElement('ul');\n  for(const name of race.horses)names.append(make('li',name));\n  details.append(names);list.append(details);\n }\n};\n$('deleteMeeting').onclick=()=>{\n const key=$('chooseMeeting').value;\n if(!key)return;\n const target=meetings.find(m=>m.date+'|'+m.track===key);\n if(!target)return;\n if(!confirm(target.date+' '+target.track+'の取り込み済み予定だけを消しますか？\\n他の開催や購入記録は残ります。'))return;\n const next=meetings.filter(m=>m!==target);\n try{localStorage.setItem(KEY,JSON.stringify(next));\n  meetings=next;show();\n  $('message').textContent=target.date+' '+target.track+'の想定予定だけを削除したで。';\n }catch(_){$('message').textContent='保存できませんでした。元の予定はそのままです。';}\n};\n$('clearAll').onclick=()=>{\n if(!meetings.length)return;\n if(!confirm('この端末に保存したJRDB想定メールの予定データを全部消しますか？ 3連単の下書き・実購入記録は消しません。'))return;\n try{localStorage.removeItem(KEY);meetings=[];show();\n $('message').textContent='想定メールの取り込みデータだけを削除したで。';}\n catch(_){$('message').textContent='削除できませんでした。ブラウザーの設定を確認してな。';}\n};\nshow();\n})();"
